<?php require __DIR__.'/../app/bootstrap.php';$u=role(['admin','kasir']);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("INSERT INTO customers(name,phone,address,notes)VALUES(?,?,?,?)");$s->execute([trim($_POST['name']),trim($_POST['phone']),trim($_POST['address']),trim($_POST['notes'])]);audit($pdo,$u['id'],'customer_create',$_POST['name']);header('Location:customers.php');exit;}$rows=$pdo->query("SELECT c.*,COUNT(t.id) n,COALESCE(SUM(t.final_cost),0) total FROM customers c LEFT JOIN tickets t ON t.customer_id=c.id GROUP BY c.id ORDER BY c.id DESC")->fetchAll();?><!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Pelanggan</title><style>body{font:14px Arial;background:#f5f7fb;margin:0}.top{background:#111827;color:#fff;padding:16px 24px}.top a{color:#fff;margin-left:14px}.wrap{max-width:1100px;margin:25px auto;padding:0 15px}.card{background:#fff;padding:18px;border-radius:12px;margin-bottom:15px}.form{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form input,.form textarea{padding:9px}.full{grid-column:1/-1}.btn{background:#2563eb;color:#fff;border:0;padding:10px;border-radius:7px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}@media(max-width:700px){.form{grid-template-columns:1fr}.full{grid-column:auto}}</style><div class=top><b>🔧 ServisPro</b><a href=index.php>Dashboard</a><a href=tickets.php>Tiket</a><a href=parts.php>Sparepart</a><a href=payments.php>Pembayaran</a><a href=logout.php>Keluar</a></div><div class=wrap><h2>Pelanggan</h2><div class=card><form method=post class=form><input type=hidden name=csrf value="<?=e(csrf())?>"><input name=name placeholder=Nama required><input name=phone placeholder=WhatsApp><input class=full name=address placeholder=Alamat><textarea class=full name=notes placeholder=Catatan></textarea><button class="btn full">Tambah</button></form></div><div class=card><table><tr><th>Nama</th><th>WhatsApp</th><th>Alamat</th><th>Tiket</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['address'])?></td><td><?=$r['n']?></td><td>Rp<?=number_format($r['total'],0,',','.')?></td></tr><?php endforeach;?></table></div></div>